import React,{useEffect,useMemo,useState} from 'react';import{Link,NavLink,Route,Routes,useNavigate,useParams}from'react-router-dom';import{ShoppingCart,Heart,Search,User,Menu,Truck,ShieldCheck,ArrowRight,Plus,Minus,Trash2,Package,CheckCircle,LogOut}from'lucide-react';import{supabase,configured}from'./supabase';
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN');const demo=[{id:'demo1',name:'Trailblazer MTB 27.5',category:'Mountain Bikes',price:14999,compare_at:17999,stock:12,featured:true,image_url:'https://images.unsplash.com/photo-1485965120184-e220f721d03e?w=1000',description:'27.5-inch mountain bike for adventures'},{id:'demo2',name:'City Glide Hybrid',category:'Hybrid Cycles',price:11999,stock:9,featured:true,image_url:'https://images.unsplash.com/photo-1571068316344-75bc76f77890?w=1000',description:'Your perfect city companion'},{id:'demo3',name:'Junior Star 20',category:'Kids Cycles',price:6999,stock:15,featured:true,image_url:'https://images.unsplash.com/photo-1511994298241-608e28f14fde?w=1000',description:'A fun ride for younger cyclists'},{id:'demo4',name:'Road Sprint 700C',category:'Road Bikes',price:22999,stock:6,image_url:'https://images.unsplash.com/photo-1541625602330-2277b4c461de?w=1000',description:'Lightweight road cycling performance'}];
